{% block title %}Event index{% endblock %}

{% block body %}
    <h1>Event index</h1>

    <table class=\"table\">
        <thead>
            <tr>
                <th>Id</th>
                <th>Title</th>
                <th>Description</th>
                <th>EventDate</th>
                <th>Location</th>
                <th>Capacity</th>
                <th>actions</th>
            </tr>
        </thead>
        <tbody>
        {% for event in events %}
            <tr>
                <td>{{ event.id }}</td>
                <td>{{ event.title }}</td>
                <td>{{ event.description }}</td>
                <td>{{ event.eventDate ? event.eventDate|date(\x27Y-m-d H:i:s\x27) : \x27\x27 }}</td>
                <td>{{ event.location }}</td>
                <td>{{ event.capacity }}</td>
                <td>
                    <a href=\"{{ path(\x27app_brouillon_show\x27, {\x27id\x27: event.id}) }}\">show</a>
                    <a href=\"{{ path(\x27app_brouillon_edit\x27, {\x27id\x27: event.id}) }}\">edit</a>
                </td>
            </tr>
        {% else %}
            <tr>
                <td colspan=\"7\">no records found</td>
            </tr>
        {% endfor %}
        </tbody>
    </table>

    <a href=\"{{ path(\x27app_brouillon_new\x27) }}\">Create new</a>
{% endblock %}
